ar');   // show pages				$info = $nav->show_info(); 		?>				<?if($rows > 0){?>	<table  width="600" cellpadding=0 cellspacing=0  class=bordertable>		<form name="formulario" action="<?=$PHP_SELF?>" method="POST">			<tr>				<td>					<table width=100% border=0 cellspacing=1 cellpadding=0>						<tr >							<td width="20" align="center"  class=maintitle valign=middle width=69>								<input type="checkbox" name="checkall" value="checkbox" onclick="ChequearTodos(this);">							</td>							<td class=maintitle width="80">Nombre</td>							<td class=maintitle width="100">Apellido</td>						</tr>		<? while($r = db_fetch_object($result)){			$class = repetition()?"row1":"row2";		?> 						<tr>							<td width="20" align="center" valign=middle nowrap width=50 class=<?=$class?>>								<input type="checkbox" name="Usuarios[<?=$r->IDEmpleado?>]" value="<?=$r->IDEmpleado?>">							</td>							<td nowrap class=<?=$class?> width="80"><? echo $r->Nombre?></td>							<td nowrap class=<?=$class?> width="100"><? echo $r->Apellidos?></td>						</tr>		<? } // END for ?>						<tr>							<td class="row1" colspan=4 nowrap width="352">								<?	print $pages; ?>							</td>						</tr>						<tr>							<td  colspan="4" align="center" class="titlemedium"  nowrap width="352">								<input type="hidden" name="mod" value="<?=$MOD?>">								<input type="hidden" name="idnot" value="<?=$idnot?>">								<input type=hidden name=action value="del">								<input type=submit name=submit value="Borrar empleados de la lista" class=submit></td>						</tr>					</table>				</td>			</tr>			</form>		</table>	<? 			}// End if$rowselse	echo "<br><br><span class=subtitle><b>No existen registros en  $TitleMod </b></span><br>";filtrar();	}// Enf function list()				?><?/*******************************************************************************************		funcion filtrar*******************************************************************************************/	function filtrar(){	Global $dblink,$total_records,$row,$numtoshow,$MOD,$idnot,$tabla_existe;	$tabla_existe = "RestriccionxUsuario";?><script>var Check = new Array("QryString","field");</script>			<table width="600" border="0"  cellspacing="1" cellpadding="0" class="tablas">			<form name="frm" action="./" method="get" onsubmit="return EvaluaReg(this,Check)">			<tr>				<td class="rowform" align="center" colspan=8>					<select name="field" id="Buscar Por" class="popup">						<option value="">Buscar Por</option>						<option value="Nombre">Nombre</option>						<option value="Apellidos">Apellidos</option>					</select> <input type="text" size="20" name="QryString" id="Buscar Por" class="post"> ordenar por <select name="order_by" class="popup">						<option value="Nombre">Nombre</option>						<option value="Apellidos">Apellidos</option>					</select>					de forma <select name="in_order" class="popup">						<option value="ASC">Ascendente</option>						<option value="DESC">Descendente</option>					</select><br>					<input type="hidden" name="mod" value="<?=$MOD?>">					<input type="hidden" name="idnot" value="<?=$idnot?>">					<input type="hidden" name="rangofield" value="Fecha">					<input type="hidden" name="action" value="list">					<input type="submit" name="submit" value="Buscar" class="submit">				</td>			</tr>			</form>	</table><?			}//End function filtrar?><?/****************************************************************************** * FUNCTIONS *****************************************************************************//*******************************************************************************************		funcion dellista($frm)*******************************************************************************************/function dellista($usu,$tabla_existe,$IDGrupo,$IDUsuario,$modulo){	GLOBAL $TitleMod,$Table,$MOD,$Key,$idnot;	$tabla_existe = "RestriccionxUsuario";	$ruta = "&id=".$id;	if(!$id){		$id=$idnot;		$ruta = "&idnot=".$id;	}		?>	<?		if(!empty($id))	{		foreach($usu as $key=>$valor)		{			$qry_existe= db_query("DELETE FROM $tabla_existe WHERE $IDGrupo=$id AND $IDUsuario=$valor");		}		?>		<script language ="JavaScript"> 					location.href='<%echo "?mod=$MOD$ruta"%>';				</script>		<?	}	else		{		echo("<center>No selecciono una lista <br>");		echo("<a href=\"javascript:history.go(-1)\" title=\"Pagina Anterior\"><< Pagina Anterior</a></center>");		}}?>